argv:
( p=26799
if [ ! -d /proc/$p ]; then echo ALREADY_ABSENT_PID_$p; exit 0; fi
check_target() {
s=$(cat /proc/$p/stat) || exit 1
s=${s##*) }
set -- $s
[ "${20}" = 60331272 ] || { echo FAIL_PID_REUSED; exit 1; }
[ "$(tr '\000' ' ' </proc/$p/cmdline)" = '/bin/sh -l ' ] || { echo FAIL_CMDLINE; exit 1; }
[ "$(readlink /proc/$p/fd/0)" = /dev/pts/0 ] || { echo FAIL_TTY; exit 1; }
}
for signal in TERM KILL; do
check_target
kill -"$signal" "$p" || exit 1
echo ${signal}_SENT_PID_$p
n=0
while [ -d /proc/$p ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n+1)); done
[ ! -d /proc/$p ] && break
done
[ ! -d /proc/$p ] || { echo FAIL_PID_STILL_PRESENT; exit 1; }
echo VERIFIED_ABSENT_PID_$p ); rc=$?; printf '\nRC=%s\n' "$rc"; if [ "$rc" -eq 0 ]; then echo DONE_CLOSE_26799; else echo FAIL_CLOSE_26799; fi

